#include "network_structures.h"
#include <assert.h>
#include <stdio.h>
enum { ROUTES=4096,FLOWS=50000 };
static FlowKey key_for(int i){FlowKey k;k.src_ip=UINT32_C(0x0a000000)+(uint32_t)i;k.dst_ip=UINT32_C(0xc0a80000)+(uint32_t)(i*17);k.src_port=(uint16_t)(1000+(i%50000));k.dst_port=(uint16_t)(80+(i%1000));k.protocol=(uint8_t)((i%2)?6:17);return k;}
int main(void){RouteTrie*t=rt_create();assert(t);assert(rt_add(t,0U,0U,1U));assert(rt_add(t,UINT32_C(0x0a000000),8U,2U));assert(rt_add(t,UINT32_C(0x0a010000),16U,3U));assert(rt_add(t,UINT32_C(0x0a010200),24U,4U));uint32_t hop=0;uint8_t len=0;bool found=false;assert(rt_lookup(t,UINT32_C(0x0a0102aa),&hop,&len,&found)&&found&&hop==4U&&len==24U);for(int i=0;i<ROUTES;++i){uint32_t p=UINT32_C(0xac100000)|((uint32_t)i<<8U);assert(rt_add(t,p,24U,(uint32_t)(1000+i)));}for(int i=0;i<ROUTES;++i){uint32_t a=UINT32_C(0xac100000)|((uint32_t)i<<8U)|77U;assert(rt_lookup(t,a,&hop,&len,&found)&&found&&len==24U&&hop==(uint32_t)(1000+i));}assert(rt_validate(t));bool removed=false;assert(rt_remove(t,UINT32_C(0x0a010200),24U,&removed)&&removed);assert(rt_lookup(t,UINT32_C(0x0a0102aa),&hop,&len,&found)&&found&&hop==3U&&len==16U);FlowTable*f=flow_create(8U);assert(f);for(int i=0;i<FLOWS;++i){bool ins=false;assert(flow_put(f,key_for(i),(uint64_t)i*11U,&ins)&&ins);}for(int i=0;i<FLOWS;++i){uint64_t v=0;bool ex=false;assert(flow_get(f,key_for(i),&v,&ex)&&ex&&v==(uint64_t)i*11U);}for(int i=0;i<FLOWS;i+=7){bool ins=true;assert(flow_put(f,key_for(i),(uint64_t)i*13U,&ins)&&!ins);}for(int i=0;i<FLOWS;i+=2){bool rm=false;assert(flow_remove(f,key_for(i),&rm)&&rm);}assert(flow_size(f)==FLOWS/2U&&flow_validate(f));printf("Network structures tests passed; route_nodes=%zu flow_capacity=%zu\n",rt_node_count(t),flow_capacity(f));flow_free(f);rt_free(t);return 0;}
